/// The localeDisplayPattern (pattern, separator) of a shipped locale.
pub(crate) fn locale_patterns(locale: &str) -> (&'static str, &'static str) {
    crate::cldr_locales::chain(locale)
        .iter()
        .find_map(|lang| own_locale_patterns(lang))
        .unwrap_or((text(28333), text(28335)))
}

fn own_locale_patterns(lang: &str) -> Option<(&'static str, &'static str)> {
    Some(match lang {
        "ar" => (text(28333), text(28334)),
        "de" => (text(28333), text(28335)),
        "en" => (text(28333), text(28335)),
        "en-Dsrt" => (text(28333), text(28335)),
        "en-Shaw" => (text(28333), text(28335)),
        "es" => (text(28333), text(28335)),
        "fr" => (text(28333), text(28335)),
        "gv" => (text(28333), text(28335)),
        "hi" => (text(28333), text(28335)),
        "it" => (text(28333), text(28335)),
        "ja" => (text(28333), text(28336)),
        "ko" => (text(28337), text(28335)),
        "ln" => (text(28333), text(28335)),
        "nl" => (text(28333), text(28335)),
        "pl" => (text(28333), text(28335)),
        "pt" => (text(28333), text(28335)),
        "ru" => (text(28333), text(28335)),
        "si" => (text(28333), text(28335)),
        "sl" => (text(28333), text(28335)),
        "sr" => (text(28333), text(28335)),
        "sr-Latn" => (text(28333), text(28335)),
        "sv" => (text(28333), text(28335)),
        "th" => (text(28333), text(28335)),
        "zh" => (text(28338), text(28339)),
        "zh-Hant" => (text(28338), text(28339)),
        "zh-Latn" => (text(28333), text(28335)),
        _ => return None,
    })
}

